// Package buildkit drives image builds via direct integration with the
// BuildKit Go client. The build graph is authored in LLB so each
// devcontainer feature install becomes its own cacheable vertex, and the
// VS Code server is fetched via llb.HTTP — the BuildKit content store
// caches it independently of the docker layer cache.
//
// A Dockerfile equivalent of the same graph is still generated by
// pkg/dockerfile for inspection and for the `generate` subcommand, but
// it's not the source of truth at build time.
package buildkit

import (
	"encoding/json"
	"fmt"
	"path"
	"sort"
	"strings"

	"github.com/distribution/reference"
	"github.com/moby/buildkit/client/llb"
	"github.com/moby/buildkit/client/llb/imagemetaresolver"
	"github.com/opencontainers/go-digest"
	ocispecs "github.com/opencontainers/image-spec/specs-go/v1"

	"github.com/wyrd-company/devcontainer-builder/pkg/features"
	"github.com/wyrd-company/devcontainer-builder/pkg/metadata"
	dcplatform "github.com/wyrd-company/devcontainer-builder/pkg/platform"
	"github.com/wyrd-company/devcontainer-builder/pkg/spec"
	"github.com/wyrd-company/devcontainer-builder/pkg/vscode"
)

// GraphInputs collects every piece of information the LLB authoring
// routine needs.
type GraphInputs struct {
	Spec     *spec.DevContainer
	Metadata metadata.CollectOptions
	// BaseImage names the FROM image. Ignored when BaseState is set.
	BaseImage string
	// BaseState, when non-nil, is used as the starting llb.State instead
	// of llb.Image(BaseImage). This is how we chain on top of a Dockerfile
	// frontend solve in the gateway path: the upstream solve produces a
	// Reference whose ToState() becomes the base for our overlays.
	BaseState    *llb.State
	Features     []features.Resolved
	VSCodeServer *vscode.Result
	// LocalContextName names the llb.Local mount that the resolved
	// feature directories will be exposed under (each feature lives at
	// _features/<SafeID>/ within that local context).
	LocalContextName string
	// FeaturesContextSubdir is the path within the local context where
	// the staged feature directories live.
	FeaturesContextSubdir string
	// RemoteUser overrides the spec's remoteUser (empty falls back to
	// the spec, then root).
	RemoteUser string
	// ImageUser is the user configured in the base image. Features see
	// it as the container user when the spec sets no containerUser.
	// Empty means root.
	ImageUser string
	// ResolveImageConfig, when true, performs a registry roundtrip at
	// LLB marshal time to inherit ENV/USER/WORKDIR from the base image.
	// Recommended; can be disabled for offline builds. Ignored when
	// BaseState is set (the upstream solve already resolved it).
	ResolveImageConfig bool
	// Platform constrains the LLB graph to the given target platform. A
	// zero-value Platform falls back to the daemon default. Authoring the
	// graph with an explicit Platform is required for cross-arch and
	// multi-platform builds — every llb.Image / llb.Run / llb.HTTP vertex
	// inherits the constraint.
	Platform dcplatform.Platform
}

// hasPlatform reports whether GraphInputs carries an explicit target
// platform (i.e. its OS/Arch are populated).
func (g GraphInputs) hasPlatform() bool {
	return g.Platform.OS != "" && g.Platform.Arch != ""
}

// ociPlatform translates the package's Platform into the OCI struct
// BuildKit's llb package expects.
func (g GraphInputs) ociPlatform() ocispecs.Platform {
	return ocispecs.Platform{
		OS:           g.Platform.OS,
		Architecture: g.Platform.Arch,
		Variant:      g.Platform.Variant,
	}
}

// constraintOpts returns the LLB constraints (currently just llb.Platform)
// that should be applied to every vertex authored by this graph.
func (g GraphInputs) constraintOpts() []llb.ConstraintsOpt {
	if !g.hasPlatform() {
		return nil
	}
	return []llb.ConstraintsOpt{llb.Platform(g.ociPlatform())}
}

// Build returns the LLB state representing the final image filesystem.
//
// Cache notes:
//
//   - Each feature install is a distinct exec vertex keyed off the
//     feature's directory contents and its option environment, so adding
//     a new feature only invalidates downstream features (in install
//     order) — it does not invalidate earlier ones.
//   - The VS Code server tarball is sourced via llb.HTTP with the SHA256
//     digest as the cache key. As long as the digest is stable, the
//     download vertex is cached even across full rebuilds.
//   - The local context (feature directories) is registered as a single
//     llb.Local with include patterns, so unrelated workspace files
//     don't bust the build cache.
func Build(in GraphInputs) (llb.State, error) {
	if in.BaseState == nil && in.BaseImage == "" {
		return llb.State{}, fmt.Errorf("buildkit: base image or base state is required")
	}

	cOpts := in.constraintOpts()

	var state llb.State
	if in.BaseState != nil {
		state = *in.BaseState
	} else {
		imageRef, err := normalizeImageRef(in.BaseImage)
		if err != nil {
			return llb.State{}, err
		}
		imageOpts := []llb.ImageOption{
			llb.WithCustomNamef("FROM %s", imageRef),
		}
		if in.ResolveImageConfig {
			imageOpts = append(imageOpts, llb.WithMetaResolver(imagemetaresolver.Default()))
		}
		if in.hasPlatform() {
			imageOpts = append(imageOpts, llb.Platform(in.ociPlatform()))
		}
		state = llb.Image(imageRef, imageOpts...)
	}

	// Local context that holds the staged feature directories. The
	// caller (builder package) is responsible for setting up an
	// fsutil.FS that exposes those directories under
	// FeaturesContextSubdir.
	var localCtx llb.State
	if len(in.Features) > 0 {
		localOpts := []llb.LocalOption{
			llb.IncludePatterns([]string{in.FeaturesContextSubdir + "/**"}),
			llb.WithCustomNamef("loading features context"),
			llb.SharedKeyHint("devcontainer-builder-features-" + in.LocalContextName),
		}
		localCtx = llb.Local(in.LocalContextName, localOpts...)
	}

	if len(in.Features) > 0 {
		containerUser, remoteUser := features.ContainerUsers(in.Spec.ContainerUser, remoteUser(in), in.ImageUser)
		state = applyBuiltinEnv(state, containerUser, remoteUser, cOpts)
	}
	for _, f := range in.Features {
		// A feature's containerEnv is visible to its own install script.
		state = withFeatureEnv(state, f.Metadata)
		state = applyFeature(state, localCtx, in.FeaturesContextSubdir, f, cOpts)
	}

	// The spec's containerEnv follows the features, as upstream orders it.
	for _, k := range sortedKeys(toStringMap(in.Spec.ContainerEnv)) {
		state = state.AddEnv(k, toStringMap(in.Spec.ContainerEnv)[k])
	}

	if in.VSCodeServer != nil {
		var err error
		state, err = applyVSCodeServer(state, in.VSCodeServer, remoteUser(in), cOpts)
		if err != nil {
			return llb.State{}, err
		}
	}

	if in.Spec.WorkspaceFolder != "" {
		state = ensureDir(state, in.Spec.WorkspaceFolder, cOpts)
		state = state.Dir(in.Spec.WorkspaceFolder)
	}
	return state, nil
}

// imageUser returns the USER of a serialized image config, or "" when
// the config is absent or unreadable.
func imageUser(config []byte) string {
	if len(config) == 0 {
		return ""
	}
	var img ocispecs.Image
	if err := json.Unmarshal(config, &img); err != nil {
		return ""
	}
	return img.Config.User
}

func normalizeImageRef(raw string) (string, error) {
	ref, err := reference.ParseNormalizedNamed(raw)
	if err != nil {
		return "", fmt.Errorf("parse image reference %q: %w", raw, err)
	}
	return reference.TagNameOnly(ref).String(), nil
}

func remoteUser(in GraphInputs) string {
	switch {
	case in.RemoteUser != "":
		return in.RemoteUser
	case in.Spec.RemoteUser != "":
		return in.Spec.RemoteUser
	case in.Spec.ContainerUser != "":
		return in.Spec.ContainerUser
	}
	return ""
}

func ensureDir(base llb.State, dir string, cOpts []llb.ConstraintsOpt) llb.State {
	runOpts := []llb.RunOption{
		llb.WithCustomNamef("create workspace folder %s", dir),
		llb.User("root"),
		llb.Args([]string{"/bin/sh", "-c", "mkdir -p " + shellQuote(dir)}),
	}
	for _, c := range cOpts {
		runOpts = append(runOpts, c)
	}
	return base.Run(runOpts...).Root()
}

// applyBuiltinEnv writes devcontainer-features.builtin.env with the
// container and remote users, then appends their home directories from
// the image's passwd database.
func applyBuiltinEnv(base llb.State, containerUser, remoteUser string, cOpts []llb.ConstraintsOpt) llb.State {
	path := features.InstallDir + "/" + features.BuiltinEnvFile
	content := llb.Scratch().File(
		llb.Mkfile("/"+features.BuiltinEnvFile, 0o644, []byte(features.BuiltinEnvContent(containerUser, remoteUser))),
		constraints(cOpts, llb.WithCustomName("feature builtin env"))...,
	)
	state := base.File(
		llb.Copy(content, "/"+features.BuiltinEnvFile, path, &llb.CopyInfo{CreateDestPath: true}),
		constraints(cOpts)...,
	)
	runOpts := []llb.RunOption{
		llb.WithCustomName("resolve feature user homes"),
		llb.User("root"),
		llb.Args([]string{"/bin/sh", "-c", features.BuiltinHomesCommand(path, containerUser, remoteUser)}),
	}
	for _, c := range cOpts {
		runOpts = append(runOpts, c)
	}
	return state.Run(runOpts...).Root()
}

// applyFeature stages the feature directory from the local context
// together with its devcontainer-features.env and install wrapper, mounts
// it at /tmp/dev-container-features/<SafeID>/ and runs the wrapper as
// root. The wrapper runs install.sh; the feature's entrypoint is a
// container entrypoint and never runs at install time.
func applyFeature(base, localCtx llb.State, subdir string, f features.Resolved, cOpts []llb.ConstraintsOpt) llb.State {
	mountTarget := features.InstallDir + "/" + f.SafeID
	srcSub := path.Join(subdir, f.SafeID)

	content := llb.Scratch().File(
		llb.Copy(localCtx, srcSub, "/", &llb.CopyInfo{CopyDirContentsOnly: true}).
			Mkfile("/"+features.EnvFile, 0o644, []byte(f.EnvFileContent())).
			Mkfile("/"+features.InstallWrapperFile, 0o755, []byte(f.InstallWrapperContent())),
		constraints(cOpts, llb.WithCustomNamef("stage feature %s", f.Metadata.ID))...,
	)

	runOpts := []llb.RunOption{
		llb.WithCustomNamef("install feature %s", f.Metadata.ID),
		llb.User("root"),
		llb.Args([]string{"/bin/sh", "-c", features.InstallCommand(mountTarget)}),
		llb.AddMount(mountTarget, content),
	}
	for _, c := range cOpts {
		runOpts = append(runOpts, c)
	}
	return base.Run(runOpts...).Root()
}

func constraints(cOpts []llb.ConstraintsOpt, extra ...llb.ConstraintsOpt) []llb.ConstraintsOpt {
	return append(append([]llb.ConstraintsOpt{}, cOpts...), extra...)
}

// applyVSCodeServer fetches the VS Code server tarball via llb.HTTP and
// extracts it into the canonical install dir, chowning to the remote
// user if necessary.
func applyVSCodeServer(base llb.State, sr *vscode.Result, user string, cOpts []llb.ConstraintsOpt) (llb.State, error) {
	if sr.SHA256 == "" {
		return llb.State{}, fmt.Errorf("vscode result missing sha256")
	}
	dgst, err := digest.Parse("sha256:" + sr.SHA256)
	if err != nil {
		return llb.State{}, fmt.Errorf("vscode digest: %w", err)
	}
	tarball := llb.HTTP(sr.URL,
		llb.Filename("vscode-server.tar.gz"),
		llb.Checksum(dgst),
		llb.WithCustomNamef("fetch vscode-server %s", short(sr.Commit)),
	)
	dir := vscode.CanonicalInstallDir(user, sr.Commit)
	cmd := fmt.Sprintf("set -e; mkdir -p %s; tar -xzf /tmp/dl/vscode-server.tar.gz -C %s --strip-components=1",
		shellQuote(dir), shellQuote(dir))
	extractOpts := []llb.RunOption{
		llb.WithCustomNamef("extract vscode-server"),
		llb.User("root"),
		llb.Args([]string{"/bin/sh", "-c", cmd}),
		llb.AddMount("/tmp/dl", tarball, llb.Readonly),
	}
	for _, c := range cOpts {
		extractOpts = append(extractOpts, c)
	}
	out := base.Run(extractOpts...).Root()

	if user != "" && user != "root" {
		home := homeOf(user)
		chown := fmt.Sprintf("if id -u %s >/dev/null 2>&1; then chown -R %s:%s %s/.vscode-server || true; fi",
			shellQuote(user), shellQuote(user), shellQuote(user), shellQuote(home))
		chownOpts := []llb.RunOption{
			llb.WithCustomNamef("chown vscode-server to %s", user),
			llb.User("root"),
			llb.Args([]string{"/bin/sh", "-c", chown}),
		}
		for _, c := range cOpts {
			chownOpts = append(chownOpts, c)
		}
		out = out.Run(chownOpts...).Root()
	}
	return out, nil
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func toStringMap(m map[string]any) map[string]string {
	out := map[string]string{}
	for k, v := range m {
		switch t := v.(type) {
		case string:
			out[k] = t
		case nil:
			out[k] = ""
		default:
			out[k] = fmt.Sprintf("%v", v)
		}
	}
	return out
}

func homeOf(user string) string {
	if user == "" || user == "root" {
		return "/root"
	}
	return "/home/" + user
}

func short(s string) string {
	if len(s) > 12 {
		return s[:12]
	}
	return s
}

func shellQuote(s string) string {
	if s == "" {
		return "''"
	}
	if !strings.ContainsAny(s, " \t\n\"'$`\\!*?[]{}()&;<>|#") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}
